import sys

def smallest_number(s: str) -> str:
    digits = list(s)
    digits.sort()
    if not digits:
        return s
    if digits[0] != '0':
        return ''.join(digits)
    # Find first non-zero digit
    first_nonzero = 0
    n = len(digits)
    while first_nonzero < n and digits[first_nonzero] == '0':
        first_nonzero += 1
    if first_nonzero == n:
        return ''.join(digits)
    # Count zeros
    zeros_count = first_nonzero
    # Put first non-zero digit first, then all zeros, then remaining digits
    result = [digits[first_nonzero]] + ['0'] * zeros_count
    # Add remaining digits (excluding the used first_nonzero)
    for i in range(n):
        if i != first_nonzero:
            result.append(digits[i])
    return ''.join(result)

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    result = smallest_number(data[0])
    sys.stdout.write(result)

if __name__ == "__main__":
    main()
